def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest contiguous run of non-background cells, horizontally
    # or vertically; this is the pattern to replicate.
    best = []
    direction = (0, 1)
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if c - start > len(best):
                best = [grid[r][x] for x in range(start, c)]
                direction = (0, 1)

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            if r - start > len(best):
                best = [grid[x][c] for x in range(start, r)]
                direction = (1, 0)

    if not best:
        return [row[:] for row in grid]

    pattern_colors = set(best)
    triggers = [
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] != bg and grid[r][c] not in pattern_colors
    ]

    out = [row[:] for row in grid]
    dr, dc = direction
    offset = len(best) // 2
    for r, c in triggers:
        for i, color in enumerate(best):
            rr = r + (i - offset) * dr
            cc = c + (i - offset) * dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
